  ('8a5e0ab1-02f9-5bce-9ee6-159579d2f7dd', null, (select id from public.skills where slug = 'rational-radical-expressions'), null, 'hard',
   $q$Evaluate $\left(\dfrac{16}{81}\right)^{-3/4}$:$q$, $q$[{"text":"$-\\dfrac{4}{27}$","is_correct":false,"misconception_token":"multiplied-base-by-exponent"},{"text":"$\\dfrac{27}{8}$","is_correct":true},{"text":"$\\dfrac{8}{27}$","is_correct":false,"misconception_token":"ignored-negative-exponent"},{"text":"$-\\dfrac{8}{27}$","is_correct":false,"misconception_token":"treated-negative-exponent-as-negative-value"}]$q$::jsonb, $q$$\dfrac{27}{8}$$q$, $q$A negative exponent flips the fraction: $\left(\dfrac{16}{81}\right)^{-3/4} = \left(\dfrac{81}{16}\right)^{3/4}$. The fourth roots are $\sqrt[4]{81} = 3$ and $\sqrt[4]{16} = 2$; cubing gives $\dfrac{27}{8}$. The choice $-\dfrac{8}{27}$ makes the value negative, but a negative exponent means a reciprocal, not a negative number.$q$, 'draft', null)
